**Input:**
```
{"file_path":"<tmp>","content":"/// Renders a user label, prefixed with the age-based category.
///
/// Shared by the public entry points so the prefix rules live in one place.
fn format_user_label(name: &str, age: u32) -> String {
    let prefix = if age >= 18 { "Adult" } else { "Minor" };
    format!("{}: {}", prefix, name)
}

pub fn process_user_a(name: &str, age: u32) -> String {
    format_user_label(name, age)
}

pub fn process_user_b(name: &str, age: u32) -> String {
    format_user_label(name, age)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn adult_label() {
        assert_eq!(format_user_label("Ada", 18), "Adult: Ada");
        assert_eq!(process_user_a("Ada", 18), "Adult: Ada");
        assert_eq!(process_user_b("Ada", 18), "Adult: Ada");
    }

    #[test]
    fn minor_label() {
        assert_eq!(format_user_label("Tim", 17), "Minor: Tim");
        assert_eq!(process_user_a("Tim", 17), "Minor: Tim");
        assert_eq!(process_user_b("Tim", 17), "Minor: Tim");
    }
}
"}
```

